  },
  mixins: [get_department_details],
  data: () => ({
    Toggle: 0,
    dropdownOption: "",
    itemsValue: [],
    depertmentItems: [],
    departments: ""
  }),
  async created() {
    // if (this.formActionType == "initiate") {
    await this.get_department_details();
